#### REQ-LENS-001-003: IAM Roles for Service Accounts (IRSA)

**Status**: Mandatory
**Rationale**: Secure access to AWS MSK using IAM authentication

**Requirements**:
- Create IAM role for Lenses.io service account
- Attach policies for MSK access (kafka:DescribeCluster, kafka:GetBootstrapBrokers, kafka:Connect)
- Attach policies for AWS Glue Schema Registry access
- Configure IRSA trust relationship with EKS OIDC provider
- Use least-privilege access principles

**Implementation**:
```hcl
# IAM Role for Lenses.io with IRSA (IAM Roles for Service Accounts)
resource "aws_iam_role" "lenses" {
  name = "lenses-platform-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRoleWithWebIdentity"
        Effect = "Allow"
        Principal = {
          Federated = module.lenses_eks_cluster.oidc_provider_arn
        }
        Condition = {
          StringEquals = {
            "${module.lenses_eks_cluster.oidc_provider}:sub" = "system:serviceaccount:lenses:lenses"
            "${module.lenses_eks_cluster.oidc_provider}:aud" = "sts.amazonaws.com"
          }
        }
      }
    ]
  })

  tags = merge(var.common_tags, {
    Name      = "lenses-platform-role-${var.environment}"
    Component = "lenses-iam"
  })
}

# IAM Policy for MSK Access
resource "aws_iam_role_policy" "lenses_msk_access" {
  name = "lenses-msk-access"
  role = aws_iam_role.lenses.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kafka-cluster:Connect",
          "kafka-cluster:DescribeCluster",
          "kafka-cluster:DescribeClusterV2",
          "kafka-cluster:DescribeClusterDynamicConfiguration"
        ]
        Resource = [
          "arn:aws:kafka:${var.aws_region}:${data.aws_caller_identity.current.account_id}:cluster/*/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kafka-cluster:ReadData",
          "kafka-cluster:DescribeTopic",
          "kafka-cluster:DescribeTopicDynamicConfiguration",
          "kafka-cluster:DescribeGroup"
        ]
        Resource = [
          "arn:aws:kafka:${var.aws_region}:${data.aws_caller_identity.current.account_id}:topic/*/*/*",
          "arn:aws:kafka:${var.aws_region}:${data.aws_caller_identity.current.account_id}:group/*/*/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kafka-cluster:WriteData",
          "kafka-cluster:CreateTopic",
          "kafka-cluster:AlterTopic",
          "kafka-cluster:DeleteTopic",
          "kafka-cluster:AlterGroup"
        ]
        Resource = [
          "arn:aws:kafka:${var.aws_region}:${data.aws_caller_identity.current.account_id}:topic/*/*/*",
          "arn:aws:kafka:${var.aws_region}:${data.aws_caller_identity.current.account_id}:group/*/*/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kafka:DescribeCluster",
          "kafka:DescribeClusterV2",
          "kafka:GetBootstrapBrokers",
          "kafka:ListClusters",
          "kafka:ListClustersV2",
          "kafka:ListNodes",
          "kafka:ListTagsForResource"
        ]
        Resource = "*"
      }
    ]
  })
}

# IAM Policy for AWS Glue Schema Registry Access
resource "aws_iam_role_policy" "lenses_schema_registry" {
  name = "lenses-schema-registry-access"
  role = aws_iam_role.lenses.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "glue:GetRegistry",
          "glue:ListRegistries",
          "glue:GetSchema",
          "glue:ListSchemas",
          "glue:GetSchemaVersion",
          "glue:ListSchemaVersions",
          "glue:GetSchemaByDefinition",
          "glue:QuerySchemaVersionMetadata",
          "glue:GetSchemaVersionsDiff"
        ]
        Resource = [
          "arn:aws:glue:${var.aws_region}:${data.aws_caller_identity.current.account_id}:registry/*",
          "arn:aws:glue:${var.aws_region}:${data.aws_caller_identity.current.account_id}:schema/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "glue:CreateSchema",
          "glue:UpdateSchema",
          "glue:DeleteSchema",
          "glue:RegisterSchemaVersion",
          "glue:UpdateRegistry",
          "glue:PutSchemaVersionMetadata"
        ]
        Resource = [
          "arn:aws:glue:${var.aws_region}:${data.aws_caller_identity.current.account_id}:registry/*",
          "arn:aws:glue:${var.aws_region}:${data.aws_caller_identity.current.account_id}:schema/*"
        ]
      }
    ]
  })
}

# IAM Policy for CloudWatch Logs
resource "aws_iam_role_policy" "lenses_cloudwatch" {
  name = "lenses-cloudwatch-access"
  role = aws_iam_role.lenses.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "arn:aws:logs:${var.aws_region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lenses/*"
      }
    ]
  })
}

# IAM Policy for Secrets Manager (to read DB password)
resource "aws_iam_role_policy" "lenses_secrets" {
  name = "lenses-secrets-access"
  role = aws_iam_role.lenses.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = [
          aws_secretsmanager_secret.db_password.arn,
          aws_secretsmanager_secret.lenses_license.arn
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.secrets.arn
      }
    ]
  })
}

# KMS Key for Secrets Manager
resource "aws_kms_key" "secrets" {
  description             = "KMS key for Lenses.io secrets encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(var.common_tags, {
    Name = "lenses-secrets-key-${var.environment}"
  })
}

resource "aws_kms_alias" "secrets" {
  name          = "alias/lenses-secrets-${var.environment}"
  target_key_id = aws_kms_key.secrets.key_id
}

# Data source for current AWS account
data "aws_caller_identity" "current" {}
```

