#### REQ-LENS-001-006: Network Configuration

**Status**: Mandatory
**Rationale**: Secure network access and connectivity

**Requirements**:
- Deploy Lenses.io in private subnets
- Configure security groups allowing only required ports (9991 Lenses UI, 3030 Admin)
- Use AWS ALB Ingress Controller for external access
- Configure TLS termination at ALB with ACM certificate
- Restrict access to VPN/corporate network via security group rules

**Implementation**:
```yaml
# Kubernetes Ingress with AWS ALB Controller
apiVersion: networking.k8s.io/v1
kind: Ingress
metadata:
  name: lenses-ingress
  namespace: lenses
  annotations:
    # ALB Controller Annotations
    alb.ingress.kubernetes.io/scheme: internal
    alb.ingress.kubernetes.io/target-type: ip
    alb.ingress.kubernetes.io/backend-protocol: HTTP
    alb.ingress.kubernetes.io/listen-ports: '[{"HTTPS":443}]'

    # SSL/TLS Configuration
    alb.ingress.kubernetes.io/certificate-arn: ${ACM_CERTIFICATE_ARN}
    alb.ingress.kubernetes.io/ssl-policy: ELBSecurityPolicy-TLS-1-2-Ext-2018-06
    alb.ingress.kubernetes.io/ssl-redirect: '443'

    # Health Check Configuration
    alb.ingress.kubernetes.io/healthcheck-protocol: HTTP
    alb.ingress.kubernetes.io/healthcheck-path: /api/v1/health
    alb.ingress.kubernetes.io/healthcheck-interval-seconds: '30'
    alb.ingress.kubernetes.io/healthcheck-timeout-seconds: '10'
    alb.ingress.kubernetes.io/healthy-threshold-count: '2'
    alb.ingress.kubernetes.io/unhealthy-threshold-count: '3'
    alb.ingress.kubernetes.io/success-codes: '200'

    # Access Control
    alb.ingress.kubernetes.io/security-groups: ${LENSES_ALB_SG}
    alb.ingress.kubernetes.io/inbound-cidrs: "${ALLOWED_CIDR_BLOCKS}"

    # WAF Configuration
    alb.ingress.kubernetes.io/wafv2-acl-arn: ${WAF_ACL_ARN}

    # Tagging
    alb.ingress.kubernetes.io/tags: Environment=${ENVIRONMENT},Application=lenses,ManagedBy=kubernetes

    # Session Stickiness
    alb.ingress.kubernetes.io/target-group-attributes: stickiness.enabled=true,stickiness.lb_cookie.duration_seconds=3600

    # Load Balancer Attributes
    alb.ingress.kubernetes.io/load-balancer-attributes: |
      idle_timeout.timeout_seconds=300,
      routing.http.drop_invalid_header_fields.enabled=true,
      routing.http2.enabled=true
spec:
  ingressClassName: alb
  rules:
  - host: lenses.${DOMAIN_NAME}
    http:
      paths:
      - path: /
        pathType: Prefix
        backend:
          service:
            name: lenses
            port:
              number: 3030
  tls:
  - hosts:
    - lenses.${DOMAIN_NAME}
```

```hcl
# Terraform Configuration for ALB and Security Groups

# Security Group for ALB
resource "aws_security_group" "lenses_alb" {
  name        = "lenses-alb-${var.environment}"
  description = "Security group for Lenses.io ALB"
  vpc_id      = var.vpc_id

  # Inbound HTTPS from allowed CIDRs
  dynamic "ingress" {
    for_each = var.allowed_cidr_blocks
    content {
      description = "HTTPS from ${ingress.value}"
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      cidr_blocks = [ingress.value]
    }
  }

  # Outbound to EKS nodes
  egress {
    description     = "HTTP to EKS nodes"
    from_port       = 3030
    to_port         = 3030
    protocol        = "tcp"
    security_groups = [module.lenses_eks_cluster.node_security_group_id]
  }

  tags = merge(var.common_tags, {
    Name = "lenses-alb-sg-${var.environment}"
  })
}

# Update EKS Node Security Group to allow ALB traffic
resource "aws_security_group_rule" "eks_from_alb" {
  description              = "Allow inbound from ALB to Lenses pods"
  type                     = "ingress"
  from_port                = 3030
  to_port                  = 3030
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.lenses_alb.id
  security_group_id        = module.lenses_eks_cluster.node_security_group_id
}

# ACM Certificate for TLS
resource "aws_acm_certificate" "lenses" {
  domain_name       = "lenses.${var.domain_name}"
  validation_method = "DNS"

  subject_alternative_names = [
    "*.lenses.${var.domain_name}"
  ]

  lifecycle {
    create_before_destroy = true
  }

  tags = merge(var.common_tags, {
    Name = "lenses-certificate-${var.environment}"
  })
}

# Route53 Record for Certificate Validation
resource "aws_route53_record" "lenses_cert_validation" {
  for_each = {
    for dvo in aws_acm_certificate.lenses.domain_validation_options : dvo.domain_name => {
      name   = dvo.resource_record_name
      record = dvo.resource_record_value
      type   = dvo.resource_record_type
    }
  }

  allow_overwrite = true
  name            = each.value.name
  records         = [each.value.record]
  ttl             = 60
  type            = each.value.type
  zone_id         = var.route53_zone_id
}

# Certificate Validation
resource "aws_acm_certificate_validation" "lenses" {
  certificate_arn         = aws_acm_certificate.lenses.arn
  validation_record_fqdns = [for record in aws_route53_record.lenses_cert_validation : record.fqdn]
}

# WAF Web ACL for ALB Protection
resource "aws_wafv2_web_acl" "lenses" {
  name  = "lenses-waf-${var.environment}"
  scope = "REGIONAL"

  default_action {
    allow {}
  }

  # AWS Managed Rules - Common Rule Set
  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 1

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        vendor_name = "AWS"
        name        = "AWSManagedRulesCommonRuleSet"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "AWSManagedRulesCommonRuleSetMetric"
      sampled_requests_enabled   = true
    }
  }

  # AWS Managed Rules - Known Bad Inputs
  rule {
    name     = "AWSManagedRulesKnownBadInputsRuleSet"
    priority = 2

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        vendor_name = "AWS"
        name        = "AWSManagedRulesKnownBadInputsRuleSet"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "AWSManagedRulesKnownBadInputsRuleSetMetric"
      sampled_requests_enabled   = true
    }
  }

  # Rate Limiting Rule
  rule {
    name     = "RateLimitRule"
    priority = 3

    action {
      block {}
    }

    statement {
      rate_based_statement {
        limit              = 2000
        aggregate_key_type = "IP"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "RateLimitRuleMetric"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "lenses-waf-metric"
    sampled_requests_enabled   = true
  }

  tags = merge(var.common_tags, {
    Name = "lenses-waf-${var.environment}"
  })
}

# Route53 A Record for Lenses
resource "aws_route53_record" "lenses" {
  zone_id = var.route53_zone_id
  name    = "lenses.${var.domain_name}"
  type    = "A"

  alias {
    name                   = kubernetes_ingress_v1.lenses.status[0].load_balancer[0].ingress[0].hostname
    zone_id                = data.aws_elb_hosted_zone_id.current.id
    evaluate_target_health = true
  }
}

# Data source for ALB hosted zone
data "aws_elb_hosted_zone_id" "current" {}
```

