  comparison_operator = "LessThanThreshold"
  evaluation_periods  = "1"
  metric_name         = "LicenseExpiryDays"
  namespace           = "Lenses"
  period              = "86400"  # 24 hours
  statistic           = "Average"
  threshold           = "30"  # Alert 30 days before expiry

  alarm_description = "Alert when Lenses.io license expires in less than 30 days"
  alarm_actions     = [aws_sns_topic.lenses_alerts.arn]

