# Lambda Function Code (lambda/license-checker/index.py)
import json
import os
import urllib.request
import boto3
from datetime import datetime

cloudwatch = boto3.client('cloudwatch')

def handler(event, context):
    lenses_url = os.environ['LENSES_URL']
    namespace = os.environ['CLOUDWATCH_NAMESPACE']
    environment = os.environ['ENVIRONMENT']

    try:
        # Call Lenses API to get license info
        req = urllib.request.Request(
            f"{lenses_url}/api/v1/license",
            headers={'Accept': 'application/json'}
        )

        with urllib.request.urlopen(req, timeout=30) as response:
            license_data = json.loads(response.read())

        # Calculate days until expiry
        expiry_date = datetime.fromisoformat(license_data['expiry'].replace('Z', '+00:00'))
        days_remaining = (expiry_date - datetime.now(expiry_date.tzinfo)).days

        # Put metric to CloudWatch
        cloudwatch.put_metric_data(
            Namespace=namespace,
            MetricData=[
                {
                    'MetricName': 'LicenseExpiryDays',
                    'Value': days_remaining,
                    'Unit': 'Count',
                    'Dimensions': [
                        {'Name': 'Environment', 'Value': environment}
                    ]
                }
            ]
        )

        return {
            'statusCode': 200,
            'body': json.dumps({
                'days_remaining': days_remaining,
                'expiry_date': license_data['expiry']
            })
        }

    except Exception as e:
        print(f"Error checking license: {str(e)}")
        return {
            'statusCode': 500,
            'body': json.dumps({'error': str(e)})
        }
